// This node fetches cryptocurrency data for multiple symbols from the free CoinPaprika API.
// It does not require an API key.

// --- LOGIC ---

// Get the incoming item from the previous node.
// We expect an array of symbols, e.g., { "json": { "symbols": ["QUBIC", "BTC"] } }
const item = items[0];
const cryptoSymbols = item.json.symbols;

if (!cryptoSymbols || !Array.isArray(cryptoSymbols) || cryptoSymbols.length === 0) {
  throw new Error('No cryptocurrency symbols provided. Please provide an array of symbols in the "symbols" field.');
}

// --- Step 1: Fetch the entire coin list once to avoid multiple API calls ---
let allCoins;
try {
  console.log("Fetching the main coin list from CoinPaprika...");
  // FIX: Added 'json: true' to ensure the response is parsed as a JSON array.
  allCoins = await this.helpers.request({ uri: 'https://api.coinpaprika.com/v1/coins', json: true });
  console.log(`Found ${allCoins.length} coins.`);
} catch (error) {
  console.error("Error fetching coin list from CoinPaprika:", error.message);
  throw new Error('Could not connect to the CoinPaprika API to get the coin list.');
}

const allResults = [];

// --- Step 2: Loop through each symbol and get its data ---
for (const symbol of cryptoSymbols) {
  console.log(`Searching for symbol: ${symbol}`);

  // Find the specific coin that matches the user's symbol from the pre-fetched list
  const coinInfo = allCoins.find(c => c.symbol.toUpperCase() === symbol.toUpperCase());

  if (!coinInfo) {
    console.warn(`Could not find a coin with the symbol "${symbol}" on CoinPaprika. Skipping.`);
    continue; // Skip to the next symbol if not found
  }

  const coinId = coinInfo.id;
  console.log(`Found ID for ${symbol}: ${coinId}. Fetching ticker data...`);

  // Fetch the Ticker Data using the Coin ID
  let tickerData;
  try {
    // Also use json: true here for consistency
    tickerData = await this.helpers.request({ uri: `https://api.coinpaprika.com/v1/tickers/${coinId}`, json: true });
  } catch (error) {
    console.error(`Error fetching ticker data for ${coinId}:`, error.message);
    continue; // Skip if there's an error for this specific coin
  }

  // --- DATA PROCESSING ---
  const quote = tickerData.quotes.USD;
  const formattedData = {
    name: tickerData.name,
    symbol: tickerData.symbol,
    price: quote.price,
    price_formatted: `$${quote.price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 8 })}`,
    market_cap: quote.market_cap,
    market_cap_formatted: `$${Math.round(quote.market_cap).toLocaleString('en-US')}`,
    volume_24h: quote.volume_24h,
    percent_change_24h: quote.percent_change_24h,
    last_updated: tickerData.last_updated,
    paprika_url: `https://coinpaprika.com/coin/${coinId}/`
  };

  allResults.push(formattedData);
  console.log(`Successfully fetched and formatted data for ${symbol}.`);
}

// Replace the incoming data with a new object containing all our results
item.json.coin_data = allResults;

// Return the item to be used by the next node
return item;

// Code1 — CoinPaprika multi-coin fetch (fixed for n8n)

// Accessing input items correctly for n8n
const inputItems = $input.all() || [];
const item = inputItems[0] || { json: {} };

// Use the symbols from the first input item, or default symbols
const cryptoSymbols = Array.isArray(item.json.symbols) && item.json.symbols.length
  ? item.json.symbols
  : ["QUBIC", "BTC"];

async function httpJSON(url) {
  // Using the older helpers method which should be available
  return this.helpers.httpRequest({
    method: 'GET',
    url,
    json: true,
    headers: { Accept: 'application/json' },
  });
}

let allCoins;
try {
  // Fixed URL: Removed extra spaces
  allCoins = await httpJSON.call(this, 'https://api.coinpaprika.com/v1/coins');
} catch (err) {
  throw new Error('Could not connect to CoinPaprika /v1/coins: ' + (err.message || err));
}

const results = [];

for (const symbol of cryptoSymbols) {
  const up = String(symbol || '').toUpperCase();
  if (!up) continue;

  // Find coin by symbol in the pre-fetched list
  const coinInfo = allCoins.find(c => String(c.symbol || '').toUpperCase() === up);
  if (!coinInfo?.id) {
    results.push({ symbol: up, error: 'Symbol not found on CoinPaprika' });
    continue;
  }

  try {
    // Fixed URL: Removed extra spaces
    const t = await httpJSON.call(this, `https://api.coinpaprika.com/v1/tickers/${coinInfo.id}`);
    const usd = t?.quotes?.USD || {};
    const price = typeof usd.price === 'number' ? usd.price : null;

    const fmtUSD = (n) => (typeof n === 'number' && isFinite(n))
      ? (n < 1 ? `$${n.toFixed(8)}` : `$${n.toFixed(2)}`)
      : null;

    results.push({
      id: coinInfo.id,
      name: t?.name || coinInfo.name || up,
      symbol: t?.symbol || up,
      price,
      price_formatted: fmtUSD(price),
      market_cap: usd.market_cap ?? null,
      market_cap_formatted: typeof usd.market_cap === 'number' ? `$${Math.round(usd.market_cap).toLocaleString('en-US')}` : null,
      volume_24h: usd.volume_24h ?? null,
      percent_change_24h: usd.percent_change_24h ?? null,
      last_updated: t?.last_updated || null,
      // Fixed URL: Removed extra spaces
      paprika_url: `https://coinpaprika.com/coin/${coinInfo.id}/`,
    });
  } catch (err) {
    results.push({ symbol: up, error: `Ticker fetch failed: ${err.message || err}` });
  }
}

// Prepare the output item
const outputItem = { json: { ...item.json, coin_data: results } };

// Return a stringified array of items to avoid "Wrong output type returned" error
return JSON.stringify([outputItem]);

/**
 * n8n Code node: ComfyUI Single Image → Video (WAN 2.2, EdgeTTS)
 *
 * Fix for "protocol mismatch": this uses plain HTTP requests to the ComfyUI REST API
 * instead of any custom ComfyUI node. Drop this into a Code node and connect it after
 * the step that produces your narration text in `item.json.output`.
 *
 * Inputs (from the current item):
 *   - json.output           → narration text (string)
 *   - json.comfyBase        → OPTIONAL, e.g. "http://127.0.0.1:8188"
 *
 * Output:
 *   - json.prompt_id        → ComfyUI prompt id
 *   - json.history          → Minimal status summary
 *   - binary.video          → final MP4 from SaveVideo (if found)
 *   - binary.audio          → TTS MP3 (if found)
 */

const COMFY_BASE = ($json.comfyBase || 'http://100.113.28.30:8188').replace(/\/$/, '');
const IMAGE_URI = 'DuckBotNewsAnchor7.png';

// Pull narration from upstream; fall back to a safe default
const narration = (typeof $json.output === 'string' && $json.output.trim())
  ? $json.output.trim()
  : "Good evening. Here's your latest crypto trading analysis.";

// Small helper
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

// --- 1) Build the ComfyUI graph (based on your provided workflow) ---
//     - Inject Windows file URI into LoadImage
//     - Inject narration into String (node 102)
//     - Also append narration to the video positive prompt (node 46)
const graph = {
  "3": {"inputs":{"seed":1075925524038446,"steps":50,"cfg":4.98,"sampler_name":"dpmpp_3m_sde_gpu","scheduler":"exponential","denoise":1,"model":["4",0],"positive":["6",0],"negative":["7",0],"latent_image":["11",0]},"class_type":"KSampler","_meta":{"title":"Audio KSampler"}},
  "4": {"inputs":{"ckpt_name":"stable-audio-open-1.0.safetensors"},"class_type":"CheckpointLoaderSimple","_meta":{"title":"Audio Model Loader"}},
  "6": {"inputs":{"text":"professional male financial analyst voice, confident and authoritative tone, clear broadcast diction for cryptocurrency news delivery, steady measured pace, close microphone presence, subtle trading floor ambiance with distant keyboard clicks and monitor hums, no background music, duration 15–30 seconds","clip":["10",0]},"class_type":"CLIPTextEncode","_meta":{"title":"Audio Positive Prompt"}},
  "7": {"inputs":{"text":"music, melody, vocals (other than the anchor), crowd noise, sirens, traffic, phone beep, UI sounds, reverb tails longer than 1.5 s","clip":["10",0]},"class_type":"CLIPTextEncode","_meta":{"title":"Audio Negative Prompt"}},
  "10": {"inputs":{"clip_name":"t5-base.safetensors","type":"stable_audio","device":"default"},"class_type":"CLIPLoader","_meta":{"title":"Audio CLIP Loader"}},
  "11": {"inputs":{"seconds":5,"batch_size":1},"class_type":"EmptyLatentAudio","_meta":{"title":"EmptyLatentAudio"}},
  "12": {"inputs":{"samples":["3",0],"vae":["4",2]},"class_type":"VAEDecodeAudio","_meta":{"title":"VAEDecodeAudio"}},
  "13": {"inputs":{"filename_prefix":"audio/ComfyUI","audioUI":"","audio":["12",0]},"class_type":"SaveAudio","_meta":{"title":"SaveAudio"}},
  "37": {"inputs":{"unet_name":"wan2.2_ti2v_5B_fp16.safetensors","weight_dtype":"fp8_e4m3fn_fast"},"class_type":"UNETLoader","_meta":{"title":"Video Model Loader"}},
  "38": {"inputs":{"clip_name":"umt5_xxl_fp8_e4m3fn_scaled.safetensors","type":"wan","device":"cpu"},"class_type":"CLIPLoader","_meta":{"title":"Video CLIP Loader"}},
  "39": {"inputs":{"vae_name":"wan2.2_vae.safetensors"},"class_type":"VAELoader","_meta":{"title":"Video VAE Loader"}},
  "46": {"inputs":{"text":"Professional Purple Sun duck news anchor in navy business suit, confident posture at news desk, animated speaking motion with subtle head movements and beak articulation, Purple Sun cosmic logo glowing behind, multiple LCD monitors displaying Bitcoin and crypto charts, financial newsroom setting, warm studio lighting, broadcast television quality, smooth animation, duck character maintaining professional demeanor while delivering crypto trading analysis","clip":["38",0]},"class_type":"CLIPTextEncode","_meta":{"title":"Video Positive Prompt"}},
  "47": {"inputs":{"text":"cartoon, anime, CGI, game render, painterly, toy-like, distorted face, extra fingers, deformed hands, text, lower third, ticker, subtitles, logo, watermark, channel bug, UI overlay, chroma-key halo, green spill, fisheye, dutch angle, skewed horizon, lowres, blurry, oversharpen halos, banding, tiling, compression artifacts, bad perspective, heavy motion blur, ghosting, frame duplication","clip":["38",0]},"class_type":"CLIPTextEncode","_meta":{"title":"Video Negative Prompt"}},
  "48": {"inputs":{"shift":8,"model":["37",0]},"class_type":"ModelSamplingSD3","_meta":{"title":"ModelSamplingSD3"}},
  "50": {"inputs":{"seed":590958479946735,"steps":25,"cfg":3.5,"sampler_name":"uni_pc","scheduler":"kl_optimal","denoise":0.9000000000000001,"model":["48",0],"positive":["46",0],"negative":["47",0],"latent_image":["55",0]},"class_type":"KSampler","_meta":{"title":"Video KSampler"}},
  "55": {"inputs":{"width":736,"height":736,"length":121,"batch_size":1,"vae":["39",0],"start_image":["56",0]},"class_type":"Wan22ImageToVideoLatent","_meta":{"title":"Wan22ImageToVideoLatent"}},
  "56": {"inputs":{"image": IMAGE_URI},"class_type":"LoadImage","_meta":{"title":"Load Image"}},
  "57": {"inputs":{"fps":30,"images":["84",0],"audio":["103",0]},"class_type":"CreateVideo","_meta":{"title":"Create Video"}},
  "58": {"inputs":{"filename_prefix":"video/Trading_News_Report","format":"mp4","codec":"auto","video":["57",0]},"class_type":"SaveVideo","_meta":{"title":"Save Video"}},
  "60": {"inputs":{"samples":["50",0],"vae":["39",0]},"class_type":"VAEDecode","_meta":{"title":"VAE Decode"}},
  "81": {"inputs":{"upscale_model":["82",0],"image":["60",0]},"class_type":"ImageUpscaleWithModel","_meta":{"title":"Upscale Video Frames"}},
  "82": {"inputs":{"model_name":"RealESRGAN_x4.pth"},"class_type":"UpscaleModelLoader","_meta":{"title":"Free 4x Upscaler Model (Connected)"}},
  "84": {"inputs":{"upscale_method":"lanczos","width":2560,"height":1440,"crop":"disabled","image":["81",0]},"class_type":"ImageScale","_meta":{"title":"Resolution Selector"}},
