}

// Always give Discord a non-empty message
if (!item.json.discordMessage || !String(item.json.discordMessage).trim()) {
  item.json.discordMessage = `Newscast 🎥 — ${item.json.output ?? ''}`.trim();
}

return items;

/**
 * generate_news_video_improved — uses your single-GPU optimized ComfyUI graph
 * - Auto-length from narration
 * - Injects narration into TTS (171) and positive prompt (105)
 * - SaveVideo MP4 with proper download
 * - Waits until job completes, then fetches MP4 into binary.video
 *
 * Expected item.json fields:
 *   $json.output       -> narration text (used by TTS + stuffed into prompt context)
 *   $json.imageUri     -> e.g. "DuckBotNewsAnchor7.png" (must be in ComfyUI/input)
 *   $json.comfyBase    -> e.g. "http://127.0.0.1:8188"
 *
 * Produces:
 *   $json.video_meta { filename, subfolder, type }  (for /view import)
 *   $json.comfyBase  (echo for downstream HTTP node)
 */
const wait = (ms)=>new Promise(r=>setTimeout(r,ms));
const randTag = () => `${Date.now()}_${Math.floor(Math.random()*1e6)}`;

const item = items[0] || { json:{}, binary:{} };
item.json ||= {};
item.binary ||= {};

const CFG = {
  base: (item.json.comfyBase || 'http://127.0.0.1:8188').replace(/\/$/,''),
  imageUri: item.json.imageUri || 'DuckBotNewsAnchor7.png',
