// ---------- EdgeTTS voice resolver ----------
async function resolveVoice(base, desired){
  try {
    const info = await httpJson.call(this, base, { method:'GET', path:'/object_info' });
    const edge = info?.EdgeTTS || info?.nodes?.EdgeTTS;
    const opt = edge?.input?.optional || {};
    const def = opt.voice;
    const choices = Array.isArray(def) && def[1] && Array.isArray(def[1].choices) ? def[1].choices : [];
    const fallback = Array.isArray(def) && def[1] && typeof def[1].default === 'string' ? def[1].default : '';
    if (!choices.length) return desired || fallback || '[English] en-US Andrew';
    // exact
    if (choices.includes(desired)) return desired;
    const dl = String(desired||'').toLowerCase();
    const ci = choices.find(c => c.toLowerCase() === dl);
    if (ci) return ci;
    const tokens = dl.split(/[^a-z0-9]+/i).filter(Boolean);
    if (tokens.length){
      const scored = choices.map(c=>{
        const cl=c.toLowerCase(); let hits=0; for (const t of tokens) if (cl.includes(t)) hits++;
        return {c,hits};
      }).filter(x=>x.hits>0).sort((a,b)=>b.hits-a.hits);
      if (scored[0]) return scored[0].c;
    }
    return fallback || choices[0];
  } catch { return desired || '[English] en-US Andrew'; }
}

